/**
 * n8n Code node — wf7 L4 step 0: plan which posts need replies.
 *
 * Fetches published posts from the last N days that have unreplied comments,
 * applies rate limiting, and outputs one item per comment that needs a reply.
 *
 * Input $json (from preceding Postgres node):
 *   posts: [{id, uid, body, purpose, threads_media_id, published_at, comment_count}]
 *   comments: [{id, comment_id, text, username, post_id, created_at, has_reply}]
 *   l4_settings: { max_replies_per_day, max_replies_per_post, cooldown_hours_per_user,
 *                  post_age_days, min_comment_length, ... }
 *   recent_replies: [{comment_id, post_id, username, published_at}]
 *
 * Output: one item per candidate comment, with post context attached.
 */

function planReplies(input) {
  const settings = input.l4_settings ?? {};
  const maxPerDay = settings.max_replies_per_day ?? 10;
  const maxPerPost = settings.max_replies_per_post ?? 5;
  const cooldownHours = settings.cooldown_hours_per_user ?? 24;
  const postAgeDays = settings.post_age_days ?? 7;
  const minCommentLen = settings.min_comment_length ?? 3;
  const now = Date.now();
  const cutoffMs = now - (postAgeDays * 24 * 60 * 60 * 1000);

  // Build lookup maps
  const postMap = new Map();
  for (const p of (input.posts ?? [])) {
    postMap.set(p.id, p);
  }

  // Count replies per post today
  const repliesPerPostToday = {};
  const repliedCommentIds = new Set();
  const repliedUsernamesRecent = new Map(); // username -> last reply timestamp

  for (const r of (input.recent_replies ?? [])) {
    const rTime = new Date(r.published_at).getTime();
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);

    if (rTime >= todayStart.getTime()) {
      repliesPerPostToday[r.post_id] = (repliesPerPostToday[r.post_id] ?? 0) + 1;
    }
    repliedCommentIds.add(r.comment_id);

    // Track cooldown per username
    if (r.username) {
      const prev = repliedUsernamesRecent.get(r.username) ?? 0;
      if (rTime > prev) repliedUsernamesRecent.set(r.username, rTime);
    }
  }

  // Filter and rank comments
  const candidates = [];
  const selfUsername = input.self_username ?? ''; // our own Threads username

  for (const c of (input.comments ?? [])) {
    // Skip if already replied
    if (repliedCommentIds.has(c.comment_id)) continue;
    if (c.has_reply) continue;

    // Skip self-replies
    if (selfUsername && c.username === selfUsername) continue;

    // Skip very short comments
    if (!c.text || c.text.trim().length < minCommentLen) continue;

    // Skip bot-like comments
    if (isBotComment(c.text)) continue;

    // Check post age
    const post = postMap.get(c.post_id);
    if (!post) continue;
    const postTime = new Date(post.published_at).getTime();
    if (postTime < cutoffMs) continue;

    // Check per-post daily cap
    const postRepliesToday = repliesPerPostToday[c.post_id] ?? 0;
    if (postRepliesToday >= maxPerPost) continue;

    // Check user cooldown
    if (c.username) {
      const lastReply = repliedUsernamesRecent.get(c.username);
      if (lastReply && (now - lastReply) < (cooldownHours * 60 * 60 * 1000)) continue;
    }

    // Score: prioritize questions, link inquiries, and recent comments
    const score = scoreComment(c, post);

    candidates.push({
      comment_id: c.comment_id,
      comment_text: c.text,
      comment_username: c.username,
      post_id: c.post_id,
      post_uid: post.uid,
      post_body: post.body,
      post_purpose: post.purpose,
      post_threads_media_id: post.threads_media_id,
      score,
    });
  }

  // Sort by score descending, cap at maxPerDay minus already-replied today
  const totalRepliedToday = Object.values(repliesPerPostToday).reduce((a, b) => a + b, 0);
  const remaining = Math.max(0, maxPerDay - totalRepliedToday);

  candidates.sort((a, b) => b.score - a.score);
  const selected = candidates.slice(0, remaining);

  return selected;
}

/**
 * Score a comment for reply priority.
 * Higher = more important to reply to.
 */
function scoreComment(comment, post) {
  let score = 0;
  const text = (comment.text ?? '').toLowerCase();

  // Questions are highest priority (they expect an answer)
  if (text.includes('?') || /\b(kenapa|macam mana|berapa|kat mana|bila|apa|siapa)\b/.test(text)) {
    score += 10;
  }

  // Link/price inquiries are high priority (they want to buy)
  if (/\b(link|beli|mana|harga|berapa rm|shopee|lazada)\b/.test(text)) {
    score += 8;
  }

  // Experience/durability questions
  if (/\b(tahan|lama|ok ke|bagus ke|berkesan|berbaloi)\b/.test(text)) {
    score += 6;
  }

  // Compliments deserve a thank-you
  if (/\b(best|bagus|comel|cantik|lawak|thank|terima kasih|nice)\b/.test(text)) {
    score += 3;
  }

  // Longer comments show more engagement
  score += Math.min(5, Math.floor((comment.text ?? '').length / 30));

  // Persona posts get slight boost (they're building community)
  if (post.purpose === 'persona') score += 2;

  // Recency boost (newer comments first)
  const ageHours = (Date.now() - new Date(comment.created_at).getTime()) / (60 * 60 * 1000);
  score += Math.max(0, 5 - Math.floor(ageHours / 6)); // up to 5 points for very recent

  return score;
}

/**
 * Detect bot-like comments (spam, emoji-only, very short generic).
 */
function isBotComment(text) {
  const t = text.trim();
  // Emoji-only
  if (/^[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\s]+$/u.test(t)) return true;
  // Generic spam patterns
  if (/^(nice|good|great|👍|🔥|💯|❤️|😍)$/i.test(t)) return true;
  // Link spam
  if (/https?:\/\/|wa\.me|t\.me|bit\.ly/i.test(t)) return true;
  // "DM me" spam
  if (/\b(dm me|pm me|message me|inbox me)\b/i.test(t)) return true;
  return false;
}

// n8n entry point
if (typeof $ !== 'undefined' && typeof $json !== 'undefined') {
  const candidates = planReplies($json);
  if (candidates.length === 0) {
    return [{ json: { ...$json, _empty: true, message: 'No comments need replies' } }];
  }
  return candidates.map(c => ({ json: { ...$json, ...c } }));
}

if (typeof module !== 'undefined') {
  module.exports = { planReplies, scoreComment, isBotComment };
}

/**
 * n8n Code node — wf7 L4 step 1: classify comment intent.
 *
 * Uses keyword/pattern matching to classify the user's comment into one of
 * 9 intent categories. This determines which reply strategy and psychology
 * techniques to apply.
 *
 * Input $json:
 *   comment_text: the user's comment
 *   post_body: the original post text (for context)
 *   post_purpose: 'product' | 'persona'
 *
 * Output: adds `intent`, `intent_confidence`, `reply_strategy`, `psychology_techniques`
 */

const INTENT_PATTERNS = {
  link_inquiry: {
    patterns: [
      /\b(link|beli (kat|di) mana|mana nak (beli|cari|dapat)|shopee|lazada|tiktok shop)\b/i,
      /\b(pm (link|harga)|drop link|bagi link|hantar link)\b/i,
      /\b(where to (buy|get)|how to (buy|order))\b/i,
    ],
    weight: 10,
  },
  price_inquiry: {
    patterns: [
      /\b(harga|berapa (rm|ringgit)|mahal|murah|berapat)\b/i,
      /\b(price|cost|how much|expensive|cheap)\b/i,
      /\b(rm\s?\d+)/i,
    ],
    weight: 9,
  },
  experience_inquiry: {
    patterns: [
      /\b(tahan (lama|berapa)|ok (ke|tak)|bagus (ke|tak)|berkesan|berbaloi)\b/i,
      /\b(pernah (guna|cuba|try)|dah (guna|cuba|pakai)|macam mana (guna|hasil))\b/i,
      /\b(worth it|recommended|review|experience|quality)\b/i,
    ],
    weight: 8,
  },
  compatibility_inquiry: {
    patterns: [
      /\b(boleh (guna|pakai|masuk)|sesuai (untuk|dengan)|compatible|support)\b/i,
      /\b(saiz|size|besar (mana|sangat)|kecil|muat)\b/i,
      /\b(iphone|android|samsung|laptop|windows|mac)\b/i,
      /\b(bateri|battery|tahan berapa (jam|hari))\b/i,
    ],
    weight: 7,
  },
  complaint: {
    patterns: [
      /\b(tak (ok|bagus|puas hati|berkesan|tahan)|rosak|rosak|problem|issue|masalah)\b/i,
      /\b(menyesal|rugi|scam|tipu|fake|palsu)\b/i,
      /\b(disappointed|broken|defective|waste of money)\b/i,
    ],
    weight: 6,
  },
  compliment: {
    patterns: [
      /\b(best|bagus|cantik|comel|lawak|nice|great|good|awesome|wow)\b/i,
      /\b(suka|sangat suka|love it|terbaik|padu|mantap)\b/i,
      /\b(thank you|terima kasih|thanks|tq)\b/i,
    ],
    weight: 4,
  },
  question: {
    patterns: [
      /\?$/,
      /\b(kenapa|macam mana|bila|apa|siapa|how|why|when|what|who)\b/i,
    ],
    weight: 5,
  },
  casual_banter: {
    patterns: [
      /\b(haha|lol|😂|🤣|kelakar|lawak)\b/i,
      /\b(same|sama|relate|setuju|betul)\b/i,
    ],
    weight: 2,
  },
};

// Psychology techniques mapped to intents
const INTENT_TECHNIQUES = {
  link_inquiry:    ['leave_better', 'calibrated_question'],
  price_inquiry:   ['tactical_empathy_label', 'leave_better'],
  experience_inquiry: ['mirror_last_three', 'leave_better'],
  compatibility_inquiry: ['calibrated_question', 'leave_better'],
  complaint:       ['tactical_empathy_label', 'bury_boomerangs', 'listen_longer'],
  compliment:      ['bury_boomerangs', 'participation_loop'],
  question:        ['mirror_last_three', 'calibrated_question'],
  casual_banter:   ['belonging_signal', 'participation_loop'],
  other:           ['listen_longer'],
};

// Reply strategies mapped to intents
const INTENT_STRATEGIES = {
  link_inquiry:    'point_to_link',
  price_inquiry:   'state_price_or_link',
  experience_inquiry: 'share_experience',
  compatibility_inquiry: 'answer_facts',
  complaint:       'empathize_and_help',
  compliment:      'thank_and_engage',
  question:        'answer_and_ask_back',
  casual_banter:   'banter_back',
  other:           'acknowledge',
};

function classifyIntent(input) {
  const text = (input.comment_text ?? '').trim();
  if (!text) return { intent: 'other', confidence: 0 };

  const scores = {};
  for (const [intent, config] of Object.entries(INTENT_PATTERNS)) {
    let score = 0;
    for (const pattern of config.patterns) {
      if (pattern.test(text)) {
        score += config.weight;
      }
    }
    if (score > 0) scores[intent] = score;
  }

  // Find highest scoring intent
  let bestIntent = 'other';
  let bestScore = 0;
  for (const [intent, score] of Object.entries(scores)) {
    if (score > bestScore) {
      bestScore = score;
      bestIntent = intent;
    }
  }

  // Confidence is normalised score (0-1)
  const maxPossible = Math.max(...Object.values(INTENT_PATTERNS).map(c =>
    c.weight * c.patterns.length));
  const confidence = maxPossible > 0 ? Math.min(1, bestScore / maxPossible) : 0;

  return {
    intent: bestIntent,
    intent_confidence: Math.round(confidence * 100) / 100,
    intent_scores: scores,
    reply_strategy: INTENT_STRATEGIES[bestIntent] ?? 'acknowledge',
    psychology_techniques: INTENT_TECHNIQUES[bestIntent] ?? ['listen_longer'],
  };
}

// n8n entry point
if (typeof $ !== 'undefined' && typeof $json !== 'undefined') {
  const result = classifyIntent($json);
  return [{ json: { ...$json, ...result } }];
}

if (typeof module !== 'undefined') {
  module.exports = { classifyIntent, INTENT_PATTERNS, INTENT_TECHNIQUES, INTENT_STRATEGIES };
}

/**
 * n8n Code node — wf7 L4 step 2: draft reply using LLM with psychology techniques.
 *
 * Input $json:
 *   comment_text: the user's comment
 *   post_body: the original post text
 *   post_purpose: 'product' | 'persona'
 *   intent: classified intent
 *   reply_strategy: strategy for this intent
 *   psychology_techniques: array of techniques to apply
 *   product_name: (optional) product name if post_purpose='product'
 *   product_notes: (optional) product notes if post_purpose='product'
 *   persona_fragment: (optional) persona calibration snippets
 *
 * Output: adds `llm_system`, `llm_user`, `draft_metadata`
 */

function buildReplyPrompt(input) {
  const intent = input.intent || 'other';
  const strategy = input.reply_strategy || 'acknowledge';
  const techniques = input.psychology_techniques || [];
  const postPurpose = input.post_purpose || 'product';

  // Build system prompt based on intent and techniques
  let systemPrompt = `You are replying to a comment on a Threads post. Write a natural, helpful reply in casual Malaysian Malay (tak/nak/dah/je/lah/kan).

Context:
- Post purpose: ${postPurpose}
- Comment intent: ${intent}
- Reply strategy: ${strategy}
`;

  if (postPurpose === 'product' && input.product_name) {
    systemPrompt += `- Product: ${input.product_name}\n`;
    if (input.product_notes) {
      systemPrompt += `- Product notes: ${input.product_notes}\n`;
    }
  }

  systemPrompt += `\nHard rules:
- Max 180 characters (strict limit)
- 1-2 sentences only
- Use casual BM: tak, nak, dah, je, lah, kan, kot
- NO Indonesian: banget, nggak, bisa, butuh, udah, bikin
- NO hard-sell: "beli sekarang", "stok terhad", "wajib ada"
- NO exclamation marks unless intent is compliment
- Sound like a helpful friend, not a salesperson
`;

  // Add technique-specific guidance
  if (techniques.length > 0) {
    systemPrompt += `\nPsychology techniques to apply:\n`;
    techniques.forEach(tech => {
      switch (tech) {
        case 'mirror_last_three':
          systemPrompt += `- mirror_last_three: Repeat their last 1-3 words as a question to invite elaboration\n`;
          break;
        case 'tactical_empathy_label':
          systemPrompt += `- tactical_empathy_label: Acknowledge their emotion with "macam [frustrated/excited/confused] je" or "faham sangat"\n`;
          break;
        case 'calibrated_question':
          systemPrompt += `- calibrated_question: Ask "macam mana" or "untuk apa" not "kenapa" — invites context\n`;
          break;
        case 'late_night_dj_voice':
          systemPrompt += `- late_night_dj_voice: Use short declarative sentences with periods, state facts plainly\n`;
          break;
        case 'bury_boomerangs':
          systemPrompt += `- bury_boomerangs: Don't pivot back to yourself, answer their question fully first\n`;
          break;
        case 'listen_longer':
          systemPrompt += `- listen_longer: Ask 2 questions before sharing your take\n`;
          break;
        case 'leave_better':
          systemPrompt += `- leave_better: Include one specific useful detail (timing, comparison, warning, tip)\n`;
          break;
        case 'participation_loop':
          systemPrompt += `- participation_loop: Ask for specific input ("korang guna yang mana?") not broad opinions\n`;
          break;
        case 'belonging_signal':
          systemPrompt += `- belonging_signal: Use "kita" for struggles, "saya" for wins\n`;
          break;
      }
    });
  }

  systemPrompt += `\nOutput ONLY the reply text. No quotes, no preamble, no explanation.`;

  // Build user prompt
  let userPrompt = `Original post:\n${input.post_body}\n\n`;
  userPrompt += `User comment:\n${input.comment_text}\n\n`;
  userPrompt += `Write a helpful 1-2 sentence reply:`;

  return {
    llm_system: systemPrompt,
    llm_user: userPrompt,
    draft_metadata: {
      intent,
      strategy,
      techniques,
      post_purpose: postPurpose,
      has_product: postPurpose === 'product' && !!input.product_name,
    },
  };
}

// n8n entry point
if (typeof $ !== 'undefined' && typeof $json !== 'undefined') {
  const result = buildReplyPrompt($json);
  return [{ json: { ...$json, ...result } }];
}

if (typeof module !== 'undefined') {
  module.exports = { buildReplyPrompt };
}

/**
 * n8n Code node — wf7 L4 step 3: QA gate for drafted replies.
 *
 * Similar to qa_persona.js but for replies. Enforces:
 *   - Length cap (180 chars default, configurable)
 *   - No hard-sell language
 *   - No Indonesian words
 *   - No link/CTA unless the user explicitly asked for a link
 *   - No making up product specs
 *   - Psychology technique validation (check the assigned technique is present)
 *   - No aggressive empathy scripts
 *
 * Input $json:
 *   reply_text: drafted reply from LLM
 *   intent: classified intent
 *   psychology_techniques: assigned techniques
 *   post_purpose: 'product' | 'persona'
 *   settings: { max_reply_length, ... }
 */

const INDONESIAN_BAN = /\b(banget|nggak|gak|aja|udah|bikin|gimana|kalian|doang|cowok|cewek|gue|deh|dong|sih)\b/i;
const FALSE_FRIENDS = [
  [/\bbisa\b/i, 'bisa = venom in BM; use boleh'],
  [/\bbutuh\b/i, 'butuh = vulgar in BM; use perlu'],
  [/\bpusing\b(?!\s+(kiri|kanan|sana))/i, 'pusing = turn in BM; use pening/sakit kepala'],
];

// Hard-sell language that should NEVER appear in replies
const HARD_SELL = /\b(beli sekarang|cepat sebelum|stok terhad|wajib ada|game.?changer|must.?have|berbaloi sangat|power gila|padu gila)\b/i;

// Link/CTA language — only allowed if intent is link_inquiry
const LINK_CTA = /\b(klik link|check.?out|order sekarang|DM saya|PM saya|wasap saya|whatsapp saya)\b/i;

// Aggressive empathy scripts (banned from psychology seed)
const AGGRESSIVE_EMPATHY = /\b(saya faham sangat (masalah|keadaan|situasi) (anda|korang|kau)|saya tahu (anda|korang|kau) rasa)\b/i;

// Psychology technique markers — used to validate that the assigned technique is present
const TECHNIQUE_MARKERS = {
  mirror_last_three: /\?\s*$/,  // ends with a question (mirroring invites elaboration)
  tactical_empathy_label: /\b(macam|nampak|faham|macam .+ je)\b/i,  // labels emotion
  calibrated_question: /\b(macam mana|untuk apa|berapa lama|kat mana)\b/i,  // asks "how/what"
  late_night_dj_voice: /^[^.!?]*\.\s*[^.!?]*\.\s*$/,  // short declarative sentences with periods
  bury_boomerangs: /\?/,  // asks about them, not pivoting to self
  listen_longer: /\?.*\?/,  // asks 2+ questions
  leave_better: /\b(tapi|sebab|kalau|tunggu|tips?|petua|cara)\b/i,  // gives useful detail
  participation_loop: /\?/,  // asks for input
  belonging_signal: /\b(kita semua|kita pun)\b/i,  // uses "kita"
  reciprocity_first: /\b(petua|tip|cara|boleh cuba)\b/i,  // gives value
};

function qaReply(input) {
  const settings = input.settings ?? {};
  const maxLen = settings.max_reply_length ?? 180;
  const reasons = [];
  let text = String(input.reply_text ?? '').trim();

  // Strip wrappers
  text = text.replace(/^```[\w]*\n?|```$/g, '').trim();
  text = text.replace(/^["'""](.*)["'""]$/s, '$1').trim();
  text = text.replace(/^(Here'?s|Reply:|Response:)\s*:?\s*/i, '').trim();

  // 1. Length
  if (text.length > maxLen) {
    reasons.push(`reply too long: ${text.length} > ${maxLen}`);
  }
  if (text.length < 3) {
    reasons.push('reply too short');
  }

  // 2. Indonesian + false friends
  if (INDONESIAN_BAN.test(text)) reasons.push('contains Indonesian word(s)');
  for (const [rx, why] of FALSE_FRIENDS) {
    if (rx.test(text)) { reasons.push(`false friend: ${why}`); break; }
  }

  // 3. Hard-sell language
  if (HARD_SELL.test(text)) reasons.push('contains hard-sell language');

  // 4. Link/CTA — only allowed if intent is link_inquiry
  if (LINK_CTA.test(text) && input.intent !== 'link_inquiry') {
    reasons.push('contains unsolicited link/CTA');
  }

  // 5. Aggressive empathy
  if (AGGRESSIVE_EMPATHY.test(text)) reasons.push('aggressive empathy script detected');

  // 6. Shouting
  const shout = (text.match(/\b[A-Z]{4,}\b/g) ?? [])
    .filter(w => !/^(RM|OK|USB|LED|PDF|XL|XXL|COD|DIY|FYI|KL|JB|PJ)$/.test(w));
  if (shout.length >= 2) reasons.push(`${shout.length} ALL-CAPS words`);

  // 7. Emoji cap (max 1 for replies)
  const emojis = text.match(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu) ?? [];
  if (emojis.length > 1) reasons.push(`${emojis.length} emoji > cap 1`);

  // 8. Psychology technique validation — at least one assigned technique should be present
  const techniques = input.psychology_techniques ?? [];
  if (techniques.length > 0) {
    const hasTechnique = techniques.some(t => {
      const marker = TECHNIQUE_MARKERS[t];
      return marker ? marker.test(text) : true;
    });
    if (!hasTechnique) {
      reasons.push(`no assigned psychology technique detected: ${techniques.join(', ')}`);
    }
  }

  // 9. Persona posts should not mention products/prices
  if (input.post_purpose === 'persona') {
    if (/\b(RM\s?\d+|harga|beli|shopee|lazada|link)\b/i.test(text)) {
      reasons.push('persona reply mentions product/price/link');
    }
  }

  // 10. No making up specs — if the reply contains numbers not in the post, flag it
  // (This is a soft check; the LLM should be prompted not to make up specs)
  const postNumbers = (input.post_body ?? '').match(/\d+/g) ?? [];
  const replyNumbers = text.match(/\d+/g) ?? [];
  const newNumbers = replyNumbers.filter(n => !postNumbers.includes(n));
  if (newNumbers.length > 2 && input.intent === 'compatibility_inquiry') {
    reasons.push('reply contains many numbers not in post (possible spec fabrication)');
  }

  return {
    pass: reasons.length === 0,
    reasons,
    cleaned: text,
    stats: {
      chars: text.length,
      emoji: emojis.length,
      intent: input.intent,
      techniques_applied: techniques,
    },
  };
}

// n8n entry point
if (typeof $ !== 'undefined' && typeof $json !== 'undefined') {
  const out = qaReply($json);
  return [{ json: { ...$json, ...out } }];
}

if (typeof module !== 'undefined') {
  module.exports = { qaReply };
}

// Prepare Threads API comment fetch URLs
const posts = $input.all().map(item => item.json);
const token = $('Load L4 config').first().json.value?.threads_token || '';

if (!token) {
  return [{ json: { _error: 'threads_token not configured in l4_reply settings' } }];
}
if (!posts.length) {
  return [{ json: { _empty: true, message: 'No posts to fetch comments for' } }];
}

const THREADS_API_BASE = 'https://graph.threads.net/v1.0';
return posts
  .filter(p => p.threads_media_id)
  .map(post => ({
    json: {
      fetch_url: `${THREADS_API_BASE}/${post.threads_media_id}/replies`,
      fetch_query: {
        access_token: token,
        fields: 'id,text,username,timestamp'
      },
      post_id: post.id,
      post_uid: post.uid,
      threads_media_id: post.threads_media_id
    }
  }));

// Process Threads API comment response
const response = $json;
const postId = $json.post_id;
const postUid = $json.post_uid;

if (response._error || response._empty) {
  return [{ json: { ...response, post_id: postId, post_uid: postUid } }];
}

const data = response.data || [];
if (!data.length) {
  return [{ json: { _empty: true, message: 'No comments returned', post_id: postId, post_uid: postUid } }];
}

return data.map(comment => ({
  json: {
    post_id: postId,
    post_uid: postUid,
    comment_id: comment.id,
    text: comment.text || '',
    username: comment.username || 'unknown',
    created_at: comment.timestamp ? new Date(comment.timestamp).toISOString() : new Date().toISOString()
  }
}));
